create table if not exists public.family_invites (id uuid primary key default gen_random_uuid(), group_id uuid not null references public.family_groups(id) on delete cascade, invited_email text not null, invited_by uuid not null references auth.users(id) on delete cascade, status text not null default 'pending' check(status in ('pending','accepted','revoked')), created_at timestamptz not null default now(), accepted_at timestamptz);
create or replace function public.create_family_group(p_name text default 'My Family') returns uuid language plpgsql security definer set search_path=public,auth as $$ declare gid uuid; begin if auth.uid() is null then raise exception 'authentication required'; end if; if exists(select 1 from public.family_members where user_id=auth.uid()) then raise exception 'already in a family'; end if; insert into public.family_groups(owner_id,name,group_type,max_members) values(auth.uid(),coalesce(nullif(trim(p_name),''),'My Family'),'family',5) returning id into gid; insert into public.family_members(group_id,user_id,name,relationship) values(gid,auth.uid(),coalesce((select raw_user_meta_data->>'full_name' from auth.users where id=auth.uid()),'Owner'),'owner'); return gid; end $$;
create or replace function public.invite_family_member(p_email text) returns uuid language plpgsql security definer set search_path=public,auth as $$ declare gid uuid; iid uuid; count_members int; begin if auth.uid() is null then raise exception 'authentication required'; end if; select id into gid from public.family_groups where owner_id=auth.uid() limit 1; if gid is null then raise exception 'family not found'; end if; select count(*) into count_members from public.family_members where group_id=gid; if count_members>=5 then raise exception 'family is full'; end if; insert into public.family_invites(group_id,invited_email,invited_by) values(gid,lower(trim(p_email)),auth.uid()) returning id into iid; return iid; end $$;
create or replace function public.accept_family_invite() returns uuid language plpgsql security definer set search_path=public,auth as $$ declare uid uuid:=auth.uid(); gid uuid; iid uuid; em text; begin if uid is null then raise exception 'authentication required'; end if; select email into em from auth.users where id=uid; select id,group_id into iid,gid from public.family_invites where lower(invited_email)=lower(em) and status='pending' order by created_at desc limit 1; if iid is null then raise exception 'no pending invite'; end if; if (select count(*) from public.family_members where group_id=gid)>=5 then raise exception 'family is full'; end if; insert into public.family_members(group_id,user_id,name,relationship) values(gid,uid,coalesce((select raw_user_meta_data->>'full_name' from auth.users where id=uid),'Family member'),'member') on conflict do nothing; update public.family_invites set status='accepted',accepted_at=now() where id=iid; return gid; end $$;
create or replace function public.submit_location_info(p_location_id uuid, p_payload jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare sid uuid; begin if auth.uid() is null then raise exception 'authentication required'; end if; insert into public.location_submissions(location_id,submitted_by,payload) values(p_location_id,auth.uid(),coalesce(p_payload,'{}'::jsonb)) returning id into sid; return sid; end $$;
create or replace function public.claim_location_for_business(p_location_id uuid,p_business_id uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare cid uuid; begin if auth.uid() is null then raise exception 'authentication required'; end if; if not exists(select 1 from public.business_members where business_id=p_business_id and user_id=auth.uid() and role in ('owner','admin','manager')) then raise exception 'business management access required'; end if; insert into public.location_claims(location_id,business_id,claimed_by) values(p_location_id,p_business_id,auth.uid()) on conflict(location_id,business_id) do update set status='pending',claimed_by=excluded.claimed_by,updated_at=now() returning id into cid; update public.location_submissions set status='claimed',claimed_business_id=p_business_id,updated_at=now() where location_id=p_location_id and status in ('accepted','pending_review','needs_correction'); return cid; end $$;
